// Case/space-insensitive view of foodImagesByName, so an order snapshot whose
// name differs only by casing or padding still resolves to the same picture.
const foodImagesByNormalizedName = Object.fromEntries(
  Object.entries(foodImagesByName).map(([name, path]) => [normalizeName(name), path])
);

function normalizeName(value) {
  return String(value == null ? '' : value).trim().replace(/\s+/g, ' ').toLowerCase();
}

/**
 * SINGLE SOURCE OF TRUTH for every food image in the app.
 *
 * Resolution order matches the Menu page exactly, so nothing on the Menu,
 * Food Details, Cart or Checkout changes:
 *   1. foodImagesByName  (exact dish name)
 *   2. foodImagesById    (stable menu item id)
 *   3. foodImagesByName  (case/whitespace-insensitive, for order snapshots)
 *   4. the item's own stored image_url / image
 *   5. '' -> components/FoodImage renders its branded placeholder
 *
 * Order rows store an item-name snapshot plus the menu item id, so passing an
 * order item here resolves the original FoodImages asset instead of whatever
 * generic photo was snapshotted onto the order.
 *
 * @param {object} item menu row or order-item snapshot (or anything with a name)
 * @returns {string} image path, or '' when there is genuinely no image
 */
export function resolveFoodImage(item) {
  if (!item) return '';
  if (typeof item === 'string') {
    return foodImagesByName[item] || foodImagesByNormalizedName[normalizeName(item)] || '';
  }

  const byName =
    foodImagesByName[item.name_en || item.name] ||
    foodImagesByName[item.name_hi] ||
    foodImagesByName[item.name_gu];
  if (byName) return byName;

  if (item.id !== undefined && item.id !== null) {
    const byId = foodImagesById[item.id];
    if (byId) return byId;
  }

  const fuzzy =
    foodImagesByNormalizedName[normalizeName(item.name_en)] ||
    foodImagesByNormalizedName[normalizeName(item.name)] ||
    foodImagesByNormalizedName[normalizeName(item.name_hi)] ||
    foodImagesByNormalizedName[normalizeName(item.name_gu)];
  if (fuzzy) return fuzzy;

  return item.image_url || item.image || '';
}

/** Convenience for order snapshots that may call the dish 'name'. */
export function resolveFoodImageByName(name, id) {
  return resolveFoodImage({ name_en: name, id });
}

